// src/store/productStore.js — Products: paged / filtered / sorted server-side (generated by make:module).

import { create } from 'zustand';
import productApi from '../services/products/productApi';

export const DEFAULT_PRODUCTS_PARAMS = { page: 1, per_page: 20, search: '', category_id: undefined, active: undefined, sort: undefined, order: undefined };

const useProductStore = create((set, get) => ({

  // ── State ──────────────────────────────────────────
  items:     [],
  total:     0,
  params:    DEFAULT_PRODUCTS_PARAMS,
  isLoading: false,
  error:     null,

  // ── Actions ────────────────────────────────────────
  fetchItems: async (changes = {}) => {
    const params = { ...get().params, ...changes };
    set({ params, isLoading: true, error: null });
    try {
      const { data } = await productApi.getAll(params);
      set({ items: data.data, total: data.meta.total });
    } catch (error) {
      set({ error: error.response?.data?.message || 'Failed to load products.' });
    } finally {
      set({ isLoading: false });
    }
  },

}));

export default useProductStore;
